/* ================= Server API =================
   window.IMORAT_API (set in config.js on the website) is the address of the Quriliş Go server.
   Without it the page runs as a self-contained demo: data stays in this browser. */
const API = String(window.IMORAT_API || "").replace(/\/+$/, "");
const NATIVE = !!(window.Capacitor && typeof window.Capacitor.isNativePlatform === "function" && window.Capacitor.isNativePlatform()); // inside the Android / iPhone app
/* the phone app (native or installed from the site): calm — no glow, no pulsing, no floating; the look switch is not offered there */
const APP_MODE = NATIVE || matchMedia("(display-mode: standalone)").matches || navigator.standalone === true;
document.documentElement.classList.toggle("app", APP_MODE);
/* API contract: the server reports its number in /api/health (server/src/app.js API_CONTRACT). It changes only when a change
   breaks older clients; the app's release build is refused on a mismatch, and a running client shows "update" instead of guessing. */
const API_CONTRACT = 1;
/* In working mode the page never shows the built-in sample catalog: it starts from the last real catalog saved in this browser
   (or from an empty one) and the server fills it in. apiState: loading | ok | offline | incompatible. */
const API_CACHE = API ? LS.get("imorat.apiCat", null) : null;
let apiState = API ? "loading" : "ok", apiHealth = null, apiCatAt = API_CACHE?.t || 0;
let apiToken = LS.get("imorat.token", ""), apiCfg = null, apiCat = API ? (API_CACHE?.cat || { rev: 0, stores: [], products: [], empty: true }) : null, myStore = LS.get("imorat.myStore", null), sellerData = null, adminStores = null, adminMasters = null;
async function api(method, path, body, opts = {}) {
  const isBlob = typeof Blob !== "undefined" && body instanceof Blob;
  const headers = {};
  if (body !== undefined) headers["Content-Type"] = isBlob ? body.type || "application/octet-stream" : "application/json";
  if (apiToken) headers.Authorization = "Bearer " + apiToken;
  let r;
  try { r = await fetch(API + path, { method, headers, body: body === undefined ? undefined : isBlob ? body : JSON.stringify(body), signal: opts.signal }); }
  catch (e) { if (e.name === "AbortError") throw e; if (!opts.probe && apiState !== "incompatible") setApiState("offline"); const er = new Error("offline"); er.code = "offline"; throw er; }
  // the server answers again: a plain call proves it is back, but the config and catalogue still have to be (re)loaded — apiBoot does that
  if (apiState === "offline" && !opts.probe) { if (apiCfg) setApiState("ok"); else if (!apiBooting) apiBoot(); }
  if (r.status === 401 && apiToken && !path.startsWith("/api/auth/")) { // the session ended elsewhere (password changed, account disabled, logout everywhere)
    apiToken = ""; LS.set("imorat.token", ""); adminToken = ""; LS.set("imorat.adminToken", "");
    if (user?.api) { user = null; try { localStorage.removeItem("imorat.user"); } catch (e) {} setTimeout(() => { renderHeader(); renderTabbar(); if (["seller", "admin"].includes(route.view)) renderMain(); toast(L("Сессия завершена — войдите снова", 1636)); }, 0); }
  }
  if (opts.raw && r.ok) return r;
  const j = await r.json().catch(() => ({}));
  if (!r.ok) { const er = new Error(j.message || "error"); er.code = j.error || "http_" + r.status; er.status = r.status; er.data = j; throw er; }
  return j;
}
