  const num = (tag.match(/^order-((?:QG|IM)-\d+)/) || [])[1];
  if (num) { openDrawer("track", num); return; }
  if (/#seller/.test(url) || /^ship-/.test(tag)) { go("seller"); return; }
  if (/#orders/.test(url)) { openDrawer("orders"); return; }
