    P.addListener("registrationError", e => console.warn("push registration", e));
    P.addListener("pushNotificationActionPerformed", a => openFromPush(a.notification?.data));
    P.addListener("pushNotificationReceived", n => { const t = n?.title || n?.data?.title; if (t) toast(`${t}${n.body ? " · " + n.body : ""}`, 6000); if (drawerView === "track" || drawerView === "orders") { ordersFetched = false; fetchOrders(); } if (route.view === "seller" && sellerData) { sellerData = null; renderSeller(); } });
    // a device already allowed earlier re-registers at every start (tokens rotate); first-time asking happens after the first order
