/* ---------- Estimate ---------- */
function dsEstimate(d) {
  const W = d.W, Lr = d.L, H = d.H, area = W * Lr, per = 2 * (W + Lr), wins = Math.max(0, d.win | 0), doors = Math.max(0, d.doors | 0);
  const wallA = Math.max(0, per * H - wins * 1.35 * 1.5 - doors * .8 * 2.05), lines = [];
  const add = (p, q, why) => { if (!p || !(q > 0)) return; const l = lines.find(x => x.p === p); if (l) { l.q += q; l.why = [l.why, why].filter(Boolean).join(" + "); } else lines.push({ p, q, why }); };
  const acc = d.accent && PROD[d.accent.pid] ? d.accent : null, accA = acc ? dsWallArea(d, acc.w) : 0, mainA = Math.max(0, wallA - accA);
  const tileLine = (p, a, why) => { const sheet = p.unit === "sheet", q = sheet ? Math.ceil(a * 1.1 / .09) : Math.ceil(a * 1.1); add(p, q, `${fmtN(a)} ${L("м²", 2336)} + 10%${why || ""}`); return a; };
  let glueA = 0;
  if (d.q.walls === "tile" && PROD[d.wtile]) glueA += tileLine(PROD[d.wtile], mainA);
  if (acc) { const p = PROD[acc.pid]; if (isTile(p)) glueA += tileLine(p, accA, L(" · стена-акцент", 27)); else { const vol = /10 л/.test(p.ru) ? 10 : 2.5, lit = accA * .12 * 2; add(p, Math.ceil(lit / vol), L(`стена-акцент ${fmtN(accA)} м² × 2 слоя`, `aksent devor ${fmtN(accA)} m² × 2 qavat`, `accent wall ${fmtN(accA)} m² × 2 coats`)); } }
  if (glueA) { add(findName(/Плиточный клей усиленный/) || byKey("glue"), Math.ceil(glueA * 5 / 25), L(`клей для стен 5 кг/м²`, 2224)); add(findName(/Затирка для швов, белая/), Math.ceil(glueA / 12), L("затирка швов", 2212)); }
  if (d.q.walls === "paint" && d.wall && mainA > 0) { const p = PROD[d.wall], vol = /10 л/.test(p?.ru || "") ? 10 : 2.5, lit = mainA * .12 * 2, wallA = mainA; add(p, Math.ceil(lit / vol), L(`${fmtN(wallA)} м² × 2 слоя = ${lit.toFixed(1).replace(".", DEC)} л`, `${fmtN(wallA)} m² × 2 qavat = ${lit.toFixed(1).replace(".", DEC)} l`, `${fmtN(wallA)} m² × 2 coats = ${lit.toFixed(1)} L`)); add(findName(/Грунтовка глубокого проникновения, 5 л/) || byKey("primer"), Math.ceil(wallA * .1 / 5), L("грунт перед покраской", 2201)); add(byKey("roller"), 1, ""); }
  if (d.q.walls === "wp") { const p = PROD[d.wp] || findName(/Обои флизелиновые «Цветы»/) || byKey("wp"); const strips = Math.ceil(per / 1.06), per1 = Math.max(1, Math.floor(10.05 / (H + .1))); add(p, Math.ceil(strips / per1), `${strips} ${L("полос", 2199)}`); }
  if (d.floor && PROD[d.floor]) { const p = PROD[d.floor], tile = p.cat === "tile"; add(p, Math.ceil(area * (tile ? 1.1 : 1.07)), `${area.toFixed(1).replace(".", DEC)} ${L("м²", 2336)} + ${tile ? 10 : 7}%`); if (tile) add(byKey("glue"), Math.ceil(area * 5 / 25), L("плиточный клей 5 кг/м²", 2282)); }
  const furn = {}; for (const it of d.items) if (it.ok !== false && PROD[it.pid]) { const q = it.krow ? it.n || 4 : 1; furn[it.pid] = (furn[it.pid] || 0) + q; }
  if (d.type === "bath") { const sinks = d.items.filter(i => i.ok !== false && ["vanity", "basin_ped"].includes(dInfo(PROD[i.pid])?.model)).length; if (sinks) add(findName(d.q.style === "loft" || d.q.style === "modern" ? /Смеситель для раковины, чёрный/ : d.q.style === "classic" ? /Смеситель для раковины, золото/ : /Смеситель для раковины, хром/), sinks, L("для раковины", 2378)); add(findName(/Вентилятор вытяжной 100 мм/), 1, L("вытяжка в ванной обязательна", 2440)); }
  const ks = d.items.filter(it => it.krow && it.ok !== false);
  if (ks.length) { const st = d.q.style, mods = ks.reduce((a, k) => a + (k.n || 4), 0), dark = st === "loft" || st === "modern";
    add(findName(st === "loft" ? /Столешница 3 м, бетон/ : st === "scandi" || st === "oriental" ? /Столешница 3 м, дуб/ : st === "modern" ? /Столешница 3 м, чёрный камень/ : /Столешница 3 м, 38 мм/), ks.reduce((a, k) => a + Math.ceil((k.n || 4) * .6 / 3), 0), L(`${fmtN(mods * .6)} м${ks.length > 1 ? ", угловая" : ""}`, `${fmtN(mods * .6)} m${ks.length > 1 ? ", burchakli" : ""}`, `${fmtN(mods * .6)} m${ks.length > 1 ? ", L-shaped" : ""}`));
    add(findName(dark ? /Мойка гранитная 60×50, чёрная/ : st === "classic" ? /Мойка гранитная 60×50, бежевая/ : /Мойка из нержавейки/), 1, "");
    add(findName(dark ? /Смеситель для кухни, чёрный/ : st === "classic" ? /Смеситель для кухни с гибким/ : /Смеситель для кухни, нержавеющая/), 1, "");
    add(findName(mods >= 7 ? /Вытяжка наклонная 90 см/ : /Вытяжка наклонная 60 см, белая/), 1, ""); }
  const mats = [...lines];
  const furnL = Object.entries(furn).map(([id, q]) => ({ p: PROD[id], q }));
  const sum = a => a.reduce((s, l) => s + minPrice(l.p) * l.q, 0);
  return { mats, furn: furnL, wallA, area, total: sum(mats) + sum(furnL), matSum: sum(mats), furnSum: sum(furnL) };
}

