function logoSquare(file, size) { // the picture whole, centred on a white square
  return new Promise((res, rej) => {
    const url = URL.createObjectURL(file), img = new Image();
    img.onload = () => { URL.revokeObjectURL(url); if (!img.width || !img.height) return rej(new Error("bad image"));
      const c = document.createElement("canvas"); c.width = c.height = size; const g = c.getContext("2d"); g.fillStyle = "#fff"; g.fillRect(0, 0, size, size);
      const k = Math.min(size / img.width, size / img.height), w = img.width * k, h = img.height * k; g.imageSmoothingQuality = "high"; g.drawImage(img, (size - w) / 2, (size - h) / 2, w, h); res(c.toDataURL("image/jpeg", .9)); };
    img.onerror = () => { URL.revokeObjectURL(url); rej(new Error("bad image")); };
    img.src = url;
  });
}
