/* ================= Smart search: typos, Latin/Cyrillic, synonyms, live suggestions ================= */
/* Every word becomes a "skeleton": Cyrillic and Uzbek Latin are written the same way (цемент = sement),
   endings are cut (ванна/ванны/ванной = vann), so «семент», «sement», «кран для ванны», «kafel» all find the right goods. */
const SK = { а: "a", б: "b", в: "v", г: "g", д: "d", е: "e", ё: "e", ж: "j", з: "z", и: "i", й: "y", к: "k", л: "l", м: "m", н: "n", о: "o", п: "p", р: "r", с: "s", т: "t", у: "u", ф: "f", х: "h", ц: "s", ч: "ch", ш: "sh", щ: "sh", ъ: "", ы: "i", ь: "", э: "e", ю: "yu", я: "ya", ў: "o", қ: "k", ғ: "g", ҳ: "h" };
function skel(t) {
  let s = String(t || "").toLowerCase().replace(/[‘ʻ'`’ʼ]/g, "").replace(/ö/g, "o").replace(/ğ/g, "g").replace(/ş/g, "sh").replace(/ç/g, "ch");
  s = s.replace(/(\d)\s*[×xх*]\s*(?=\d)/g, "$1×").replace(/(\d),(?=\d)/g, "$1.");
  s = s.replace(/[а-яёўқғҳ]/g, c => SK[c] ?? c);
  return s.replace(/ts/g, "s").replace(/c(?!h)/g, "s").replace(/q/g, "k").replace(/x/g, "h").replace(/w/g, "v").replace(/yo/g, "e");
}
const SK_END = ["iyami", "yami", "ami", "ogo", "ego", "omu", "emu", "imi", "iyah", "yah", "ah", "aya", "yaya", "iya", "oe", "ee", "ie", "ye", "iy", "yy", "oy", "uyu", "yuyu", "om", "em", "am", "yam", "ov", "ev", "ey", "ya", "yu", "a", "e", "i", "o", "u", "y"];
function stem(w) {
  if (/\d/.test(w)) return w;
  w = w.replace(/^(.{3,}[aeiou])gi$/, "$1k"); // Uzbek: eshik → eshigi
  let m = w.match(/^(.{4,}?)(larining|larini|larni|larga|larda|lardan|lari|lar|ning|dan|ga|da|ni)$/); if (m) w = m[1];
  for (const e of SK_END) if (w.length - e.length >= 3 && w.endsWith(e)) return w.slice(0, -e.length);
  return w;
}
